"""PreToolUse hook: block hand edits to generated files.

docs/TRACEABILITY.md is produced by `make check`. Editing it by hand is the one way the
traceability matrix could say something the tests do not.
"""

import json
import sys
from pathlib import Path

GENERATED = ("docs/TRACEABILITY.md",)


def main() -> int:
    payload = json.load(sys.stdin)
    file_path = payload.get("tool_input", {}).get("file_path", "")
    if not file_path:
        return 0
    project = Path(payload.get("cwd", ".")).resolve()
    target = Path(file_path).resolve()
    for rel in GENERATED:
        if target == (project / rel).resolve():
            print(
                f"{rel} is generated by `make check` (scripts/traceability.py). "
                "Change the tests or requirements.yaml instead.",
                file=sys.stderr,
            )
            return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
